BASE_THRESHOLD = 0.0   # initial threshold (neutral)
THRESHOLD_INCREASE = 0.02  # per round increase in threshold (becomes stricter)
FORGIVENESS_BONUS = 0.2   # extra trust when own cooperation is high
HARSHNESS_PENALTY = 0.2   # extra strictness when own cooperation is low

def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    # basic score: cooperate = +1, defect = -1
    if action == 'cooperate':
        rep_val = 1.0
    else:
        rep_val = -1.0

    # modulate based on own cooperation history (only if enough history)
    if len(my_history) >= 5:
        own_coop_rate = sum(my_history) / len(my_history)
        if own_coop_rate > 0.7:
            # if I am highly cooperative, be more forgiving
            if action == 'cooperate':
                rep_val = min(1.0, rep_val + FORGIVENESS_BONUS)
            else:
                rep_val = max(-1.0, rep_val + FORGIVENESS_BONUS)  # defect less severely penalized
        elif own_coop_rate < 0.3:
            # if I am highly defecting, be harsher
            if action == 'defect':
                rep_val = max(-1.0, rep_val - HARSHNESS_PENALTY)  # defect more severely penalized
            else:
                rep_val = min(1.0, rep_val - HARSHNESS_PENALTY)   # cooperate less rewarded

    # weighted moving average
    new_rep = ALPHA * rep_val + (1 - ALPHA) * current_reputation
    return max(-1.0, min(1.0, new_rep))

def decide(recipient_reputation, round_num, my_history):
